INSERT OR REPLACE INTO gtm_drafts (id, topic_id, channel, content, citations, approval_status, approved_by, approved_at) VALUES ('draft-1', 'top-1', 'linkedin', 'Most founders believe hosting a full-stack SaaS costs $50-$200/month in early server and database fees.

Here is the exact $0 production architecture running Signhify Studio:
• Frontend: Cloudflare Pages (unlimited edge bandwidth)
• Backend: Cloudflare Workers (100,000 requests/day free)
• Database: Cloudflare D1 (Serverless SQLite, 5M reads/day)
• Storage: Cloudflare R2 (10 GB free, ZERO egress fees)
• LLM Gateway: Cloudflare Workers AI + Groq fallback (0ms server spinup)

Never burn cash on infrastructure before validating demand. Code lean, measure latency, ship today.', '["https://pages.cloudflare.com","https://developers.cloudflare.com/d1","https://groq.com"]', 'UNDER_REVIEW', NULL, NULL);
INSERT OR REPLACE INTO gtm_drafts (id, topic_id, channel, content, citations, approval_status, approved_by, approved_at) VALUES ('draft-2', 'top-1', 'x', 'Stop paying $20/mo for managed Postgres before you have 10 users.

Cloudflare D1 gives you:
- 5M reads / day
- 100K writes / day
- 5GB storage
- Zero connection pool starvation

Cost: $0. Pair it with Cloudflare Workers for sub-15ms edge responses. 🧵👇', '["https://developers.cloudflare.com/d1"]', 'APPROVED', 'Piyush Raj Singh', '2026-11-07T11:20:00Z');
INSERT OR REPLACE INTO rag_documents (id, title, content, metadata) VALUES ('doc-1', 'Cloudflare Pages & Workers Free Tier Limits', 'Cloudflare Pages offers unlimited requests and bandwidth on the free tier, with up to 500 builds per month and 100 custom domains per account.
Cloudflare Workers provides 100,000 requests per day on the free tier with up to 10 milliseconds of CPU execution time per request. Workers execute across 300+ global data centers with near-zero cold starts.
Commercial usage is 100% permitted under Cloudflare''s standard terms of service.', '{"source":"Cloudflare Docs","category":"Hosting"}');
INSERT OR REPLACE INTO rag_documents (id, title, content, metadata) VALUES ('doc-2', 'Cloudflare D1 & R2 Quotas and Invariants', 'Cloudflare D1 free tier includes 5,000,000 rows read per day, 100,000 rows written per day, and 5 GB of total storage. D1 is an edge-native SQLite engine.
Cloudflare R2 provides 10 GB of object storage per month, 1,000,000 Class A operations (writes/lists), and 10,000,000 Class B operations (reads). Unlike Amazon S3, R2 has zero data egress fees.', '{"source":"Cloudflare Docs","category":"Database & Storage"}');
INSERT OR REPLACE INTO rag_documents (id, title, content, metadata) VALUES ('doc-3', 'Signhify Studio GTM Approval Gate Rules', 'Every piece of outbound content drafted by AI in Signhify GTM Autopilot OS MUST pass through a human approval gate.
No post may be scheduled, published, or transmitted to social APIs (LinkedIn, X, Ghost) without an explicit approval status of APPROVED recorded in the database.
If any fact or claim in the draft lacks a verified citation, the content generator must flag the draft as UNDER_REVIEW with a warning badge.', '{"source":"Signhify Operational Playbook","category":"GTM Governance"}');
